WITH exploded AS (SELECT id, effective_from, currency, EXPLODE_OUTER(tier_limits) AS element FROM price_tiers) SELECT currency, DATE_TRUNC('YEAR', effective_from) AS year_start, COUNT_IF(currency = 'THB') AS thb_events, SUM(element) FILTER (WHERE currency = 'EUR') AS eur_total_element, COUNT(DISTINCT currency) AS distinct_currencies FROM exploded GROUP BY currency, DATE_TRUNC('YEAR', effective_from) HAVING COUNT(DISTINCT currency) < 1000
